  "args": {
    "old_content": "    // mux_in[0] (ab=00): 0,1,1,1 => c OR d
    // mux_in[1] (ab=01): 0,0,0,0 => 0
    // mux_in[2] (ab=11): 0,0,1,0 => c AND d
    // mux_in[3] (ab=10): 1,0,1,1 => c OR (~d)

    assign mux_in[0] = c | d;
    assign mux_in[1] = 1'b0;
    assign mux_in[2] = c & d;
    assign mux_in[3] = c | ~d;",
    "new_content": "    // Implement each mux_in bit directly from the K-map.
    // cd rows ordered as: 00, 01, 11, 10.
    // ab columns: 00->mux_in[0], 01->mux_in[1], 11->mux_in[2], 10->mux_in[3].

