    // mux_in[1] (ab=01): values => 0,0,0,0 => 0
    // mux_in[2] (ab=11): values => 0,0,1,0 => c & d
    // mux_in[3] (ab=10): values => 1,0,1,1 => (~c) OR d

    assign mux_in[0] = c | d;
    assign mux_in[1] = 1'b0;
    assign mux_in[2] = c & d;
    assign mux_in[3] = (~c) | d;"
  }
}

